+        } finally {
+            FileWriteEvent.offer(start, null, written);
+        }
+    }
+
+    // decided at the first write where Blocker.tryNonBlockingFirst() holds
+    private int mode() {
+        int m = mode;
+        if (m == UNKNOWN) {
+            boolean attempted = Blocker.begin();
+            try {
