+    /** True if fd is open on a FIFO (a named or an anonymous pipe); false if it cannot tell. */
+    public static boolean isFifo(int fd) {
+        try {
+            int type = UnixFileAttributes.get(fd).mode() & UnixConstants.S_IFMT;
